"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Input } from "@/components/ui/input";
import { Star } from "lucide-react";
import Topbar from "@/components/Topbar";
import { useUser } from "@stackframe/stack";

interface Interview {
  id: number;
  role: string;
  interview_type: string;
  experience_level: string;
  num_questions: number;
  questions: string[];
  responses: string[];
  feedback: object;
  created_at: string;
}

export default function InterviewsPage() {
  const user = useUser();
  const router = useRouter();
  const [isScrolled] = useState(false);
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sheetOpen, setSheetOpen] = useState(false);
  const [currentInterview, setCurrentInterview] = useState<Interview | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [userResponse, setUserResponse] = useState("");
  const [chatMessages, setChatMessages] = useState<{type: 'ai' | 'user', content: string}[]>([]);


  useEffect(() => {
    if (!user) {
      router.push("/auth/signin");
    }
  }, [user, router]);

  useEffect(() => {
    fetchInterviews();
  }, []);

  const fetchInterviews = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/interviews/');
      if (response.ok) {
        const data = await response.json();
        setInterviews(data);
      }
    } catch (error) {
      console.error('Error fetching interviews:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleUserResponse = () => {
    if (!userResponse.trim() || !currentInterview) return;

    // Add user message
    setChatMessages(prev => [...prev, {type: 'user', content: userResponse}]);

    // Add AI response with next question or end
    const nextIndex = currentQuestionIndex + 1;
    if (nextIndex < currentInterview.questions.length) {
      setChatMessages(prev => [...prev, {type: 'ai', content: `Good answer! Next question: ${currentInterview.questions[nextIndex]}`}]);
      setCurrentQuestionIndex(nextIndex);
    } else {
      setChatMessages(prev => [...prev, {type: 'ai', content: 'Great! You\'ve completed the interview. Thank you for participating!'}]);
    }

    setUserResponse("");
  };

  const generateInterview = async () => {
    const defaultRole = "Software Engineer";
    const defaultType = "technical";
    const defaultLevel = "intermediate";
    const defaultNumQuestions = 5;

    setSheetOpen(true);
    setGenerating(true);
    try {
      const response = await fetch('/api/interviews/create/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          role: defaultRole,
          type: defaultType,
          level: defaultLevel,
          num_questions: defaultNumQuestions,
        }),
      });

      if (response.ok) {
        const newInterview = await response.json();
        setInterviews([newInterview, ...interviews]);
        setCurrentInterview(newInterview);
        setCurrentQuestionIndex(0);
        setChatMessages([{type: 'ai', content: `Welcome! Let's start your ${newInterview.role} interview. Here's the first question: ${newInterview.questions[0]}`}]);
      } else {
        alert('Error generating interview');
      }
    } catch (error) {
      console.error('Error generating interview:', error);
      alert('Error generating interview');
    } finally {
      setGenerating(false);
      setSheetOpen(false);
    }
  };

  if (!user) {
    return null;
  }

  return (
    <div className="h-screen bg-slate-900 text-foreground font-sans relative overflow-hidden">
      {/* Mobile Sidebar Overlay */}
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-30 md:hidden" onClick={() => setSidebarOpen(false)} />
      )}

      {/* Custom Layout Grid */}
      <div className="h-full grid grid-cols-1 gap-0 md:grid-cols-[16rem_1fr]">
        {/* Sidebar */}
        <div className={`h-full bg-slate-800 border-r border-slate-600 shadow-lg z-40 transition-transform duration-300 md:translate-x-0 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} md:relative md:translate-x-0`}>
          {/* Mobile Close Button */}
          <button
            onClick={() => setSidebarOpen(false)}
            className="md:hidden absolute top-4 right-4 text-slate-300 hover:text-white transition-colors duration-200 z-50"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
          <div className="border-b border-slate-600 p-6">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 bg-purple-400 rounded-xl flex items-center justify-center">
                <span className="text-white font-bold text-lg">AI</span>
              </div>
              <div>
                <h3 className="text-white font-bold text-lg">AINEX</h3>
                <p className="text-slate-300 text-xs">Interview Platform</p>
              </div>
            </div>
            <nav className="space-y-2">
              <button
                className="w-full flex items-center gap-3 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors duration-300 rounded-lg p-3"
                onClick={() => {
                  router.push('/dashboard');
                  setSidebarOpen(false);
                }}
              >
                <svg className="text-slate-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
                </svg>
                <span>Dashboard</span>
              </button>
              <button
                className="w-full flex items-center gap-3 text-purple-400 bg-slate-700 hover:bg-slate-600 hover:text-white transition-colors duration-300 rounded-lg p-3"
                onClick={() => {
                  // Already on interviews page
                  setSidebarOpen(false);
                }}
              >
                <svg className="text-purple-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                <span>Interviews</span>
              </button>
              <button className="w-full flex items-center gap-3 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors duration-300 rounded-lg p-3">
                <svg className="text-slate-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
                <span>Profile</span>
              </button>
            </nav>
          </div>
          <div className="p-4">
            <div className="mb-4">
              <h4 className="text-slate-200 font-semibold text-sm uppercase tracking-wider">Navigation</h4>
            </div>
            <nav className="space-y-2">
              <button
                className="w-full flex items-center gap-3 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors duration-300 rounded-lg p-3"
                onClick={() => {
                  router.push('/dashboard');
                  setTimeout(() => {
                    const recentSection = document.getElementById('recent-interviews');
                    if (recentSection) {
                      recentSection.scrollIntoView({ behavior: 'smooth' });
                    }
                  }, 100);
                  setSidebarOpen(false);
                }}
              >
                <svg className="text-slate-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3a2 2 0 012-2h4a2 2 0 012 2v4m-6 9l6-6m0 0v6m0-6h-6" />
                </svg>
                <span>Recent Interviews</span>
              </button>
              <button
                className="w-full flex items-center gap-3 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors duration-300 rounded-lg p-3"
                onClick={() => {
                  router.push('/dashboard');
                  setTimeout(() => {
                    const communitySection = document.getElementById('community');
                    if (communitySection) {
                      communitySection.scrollIntoView({ behavior: 'smooth' });
                    }
                  }, 100);
                  setSidebarOpen(false);
                }}
              >
                <svg className="text-slate-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
                </svg>
                <span>Community</span>
              </button>
            </nav>
          </div>
          <div className="border-t border-slate-600 p-4">
            <nav>
              <button className="w-full flex items-center gap-3 text-slate-300 hover:bg-slate-700 hover:text-white transition-colors duration-300 rounded-lg p-3">
                <svg className="text-slate-400 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                <span>Settings</span>
              </button>
            </nav>
          </div>
        </div>

        {/* Main Content Area */}
        <div className="h-screen flex flex-col min-w-0">
          <Topbar isScrolled={isScrolled} onMenuToggle={() => setSidebarOpen(!sidebarOpen)} />
          <div className="h-[calc(100vh-4rem)] overflow-auto">
            <div className="container mx-auto px-8 py-8">
              {/* Header */}
              <div className="mb-8">
                <h1 className="text-4xl font-display text-white mb-2">
                  <span className="text-purple-400">Interviews</span>
                </h1>
                <div className="w-24 h-1 bg-purple-400 rounded-full"></div>
              </div>

              {/* Generate Interview Form */}
              <section className="mb-8">
                <Card className="p-6 bg-slate-800 border-slate-600">
                  <CardHeader>
                    <CardTitle className="text-white">Generate New Interview</CardTitle>
                    <CardDescription className="text-gray-300">Create a new AI-powered interview</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
                      <SheetTrigger asChild>
                        <Button
                          disabled={generating}
                          className="bg-purple-600 hover:bg-purple-700 text-white"
                        >
                          {generating ? 'Generating...' : 'Generate Interview'}
                        </Button>
                      </SheetTrigger>
                      <SheetContent side="right" className="w-[800px] sm:w-[1200px] bg-slate-800 border-slate-600">
                        <SheetHeader>
                          <SheetTitle className="text-white">
                            {currentInterview ? `${currentInterview.role} Interview Chat` : 'Generating Interview'}
                          </SheetTitle>
                        </SheetHeader>
                        <div className="mt-4 text-gray-300 h-full flex flex-col">
                          {currentInterview ? (
                            <>
                              <div className="flex-1 overflow-y-auto space-y-4 p-4">
                                {chatMessages.map((msg, index) => (
                                  <div key={index} className={`flex ${msg.type === 'user' ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[70%] p-3 rounded-lg ${msg.type === 'user' ? 'bg-purple-600 text-white' : 'bg-slate-700 text-gray-200'}`}>
                                      {msg.content}
                                    </div>
                                  </div>
                                ))}
                              </div>
                              {currentQuestionIndex < currentInterview.questions.length && (
                                <div className="p-4 border-t border-slate-600">
                                  <div className="flex gap-2">
                                    <Input
                                      value={userResponse}
                                      onChange={(e) => setUserResponse(e.target.value)}
                                      placeholder="Type your answer..."
                                      className="bg-slate-700 border-slate-600 text-white"
                                      onKeyPress={(e) => e.key === 'Enter' && handleUserResponse()}
                                    />
                                    <Button onClick={handleUserResponse} className="bg-purple-600 hover:bg-purple-700">
                                      Send
                                    </Button>
                                  </div>
                                </div>
                              )}
                            </>
                          ) : (
                            <div className="flex items-center justify-center py-8">
                              <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-400"></div>
                            </div>
                          )}
                        </div>
                      </SheetContent>
                    </Sheet>
                  </CardContent>
                </Card>
              </section>

              {/* Interviews List */}
              <section>
                <div className="flex items-center gap-4 mb-8">
                  <div className="p-3 bg-slate-800 rounded-2xl border border-slate-600">
                    <svg className="size-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                  </div>
                  <div>
                    <h2 className="text-4xl font-display text-white mb-2">
                      Your{' '}
                      <span className="text-purple-400">Interviews</span>
                    </h2>
                    <div className="w-24 h-1 bg-purple-400 rounded-full"></div>
                  </div>
                </div>
                {loading ? (
                  <div className="text-center text-gray-400 py-16">
                    <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-400 mx-auto mb-4"></div>
                    <p className="text-xl">Loading interviews...</p>
                  </div>
                ) : interviews.length > 0 ? (
                  <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
                    {interviews.map((interview) => (
                      <Card key={interview.id} className="p-6 bg-slate-800 border-slate-600 hover:border-slate-500 hover:shadow-lg transition-all duration-300 group rounded-2xl">
                        <CardHeader className="pb-4">
                          <div className="flex items-center justify-between mb-2">
                            <div className="w-12 h-12 bg-purple-400 rounded-xl flex items-center justify-center">
                              <Star className="w-6 h-6 text-white" />
                            </div>
                            <span className="text-xs text-slate-300 bg-slate-700 px-2 py-1 rounded-full">Active</span>
                          </div>
                          <CardTitle className="text-white text-xl group-hover:text-purple-300 transition-colors duration-300 font-bold">{interview.role}</CardTitle>
                          <CardDescription className="text-gray-300 group-hover:text-gray-200 transition-colors duration-300 text-base">
                            {interview.interview_type} • {interview.experience_level} • {interview.num_questions} questions
                          </CardDescription>
                        </CardHeader>
                        <CardContent>
                          <div className="text-gray-400 text-sm mb-6 group-hover:text-gray-300 transition-colors duration-300">
                            Created: {new Date(interview.created_at).toLocaleDateString()}
                          </div>
                          <div className="flex gap-3">
                            <Button
                              size="sm"
                              className="bg-purple-600 hover:bg-purple-700 text-white shadow-lg transition-colors duration-300 rounded-lg flex-1"
                              onClick={() => router.push(`/interview/${interview.id}`)}
                            >
                              View Questions
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              className="border-red-500 text-red-400 hover:bg-red-500 hover:text-white hover:border-red-400 transition-colors duration-300 rounded-lg"
                              onClick={() => {
                                if (confirm('Are you sure you want to delete this interview?')) {
                                  // Delete interview logic here
                                }
                              }}
                            >
                              Delete
                            </Button>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                ) : (
                  <div className="text-center text-gray-400 py-16 bg-slate-800 rounded-2xl border border-slate-600">
                    <div className="w-20 h-20 bg-slate-700 rounded-full flex items-center justify-center mx-auto mb-6">
                      <svg className="size-10 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                    </div>
                    <p className="text-2xl mb-2">No interviews generated yet</p>
                    <p className="text-gray-500">Use the form above to create your first interview</p>
                  </div>
                )}
              </section>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}